// Generated by export_course.py; edit content.py/curriculum_extra.py instead.
export const COURSE = [{"title":"Основы SQL","topic":"SELECT · FROM · LIMIT","theory":"SQL помогает задавать вопросы таблицам. SELECT выбирает столбцы, FROM указывает таблицу, LIMIT ограничивает число строк.","example":"SELECT name, city\nFROM users\nLIMIT 3;","required":null,"tasks":[{"title":"Имена пользователей","prompt":"Выведи имена всех пользователей.","solution":"SELECT name FROM users","hint1":"Начни с SELECT name.","hint2":"Таблица называется users.","explanation":"SELECT выбирает только столбец name.","mode":"read","target":null,"required":null},{"title":"Первые три товара","prompt":"Покажи название и цену первых трёх товаров.","solution":"SELECT name, price FROM products LIMIT 3","hint1":"Нужны два столбца.","hint2":"Используй LIMIT 3 после FROM products.","explanation":"LIMIT оставляет три первые строки в исходном порядке.","mode":"read","target":null,"required":null},{"title":"Все данные","prompt":"Выведи все столбцы таблицы users.","solution":"SELECT * FROM users","hint1":"Звёздочка означает все столбцы.","hint2":"После FROM укажи users.","explanation":"SELECT * показывает полные строки таблицы.","mode":"read","target":null,"required":null},{"title":"Адреса почты","prompt":"Выведи id и email всех пользователей.","solution":"SELECT id, email FROM users","hint1":"Перечисли два столбца после SELECT.","hint2":"Между столбцами поставь запятую.","explanation":"Список после SELECT определяет форму результата.","mode":"read","target":null,"required":null},{"title":"Каталог","prompt":"Выведи id, name и category всех товаров.","solution":"SELECT id, name, category FROM products","hint1":"Товары лежат в products.","hint2":"Выбери три указанных столбца.","explanation":"FROM products направляет запрос к каталогу товаров.","mode":"read","target":null,"required":null},{"title":"Псевдоним","prompt":"Покажи name товара под названием product_name.","solution":"SELECT name AS product_name FROM products","hint1":"Для переименования есть AS.","hint2":"Псевдоним пишется после имени столбца.","explanation":"AS меняет имя столбца в результате, не меняя таблицу.","mode":"read","target":null,"required":null},{"title":"Вычисляемый столбец · финал","prompt":"Покажи name и double_price, равный price * 2, для каждого товара.","solution":"SELECT name, price * 2 AS double_price FROM products","hint1":"Выражения можно писать после SELECT.","hint2":"Умножь price на 2 и добавь AS double_price.","explanation":"SQL умеет вычислять новые столбцы прямо в запросе.","mode":"read","target":null,"required":null}]},{"title":"Фильтрация","topic":"WHERE · AND · OR · IN · LIKE","theory":"WHERE оставляет строки, которые удовлетворяют условию. Условия можно соединять через AND и OR; LIKE ищет по шаблону, IN проверяет набор значений.","example":"SELECT name\nFROM users\nWHERE age >= 18;","required":null,"tasks":[{"title":"Совершеннолетние","prompt":"Выведи имена пользователей старше 25 лет.","solution":"SELECT name FROM users WHERE age > 25","hint1":"Добавь условие WHERE.","hint2":"Возраст должен быть строго больше 25.","explanation":"WHERE фильтрует строки до вывода результата.","mode":"read","target":null,"required":null},{"title":"Жители Москвы","prompt":"Покажи имена и возраст пользователей из Москвы.","solution":"SELECT name, age FROM users WHERE city = 'Москва'","hint1":"Сравни столбец city.","hint2":"Строковое значение заключи в одинарные кавычки.","explanation":"Условие по городу оставило только подходящих пользователей.","mode":"read","target":null,"required":null},{"title":"Возрастной порог","prompt":"Покажи name и age пользователей от 18 лет включительно.","solution":"SELECT name, age FROM users WHERE age >= 18","hint1":"Добавь WHERE по age.","hint2":"Включительно означает >=.","explanation":"WHERE проверяет условие отдельно для каждой строки.","mode":"read","target":null,"required":null},{"title":"Два условия","prompt":"Выведи имена пользователей из Москвы старше 25 лет.","solution":"SELECT name FROM users WHERE city = 'Москва' AND age > 25","hint1":"Нужны два условия.","hint2":"Соедини их оператором AND.","explanation":"AND требует выполнения обоих условий.","mode":"read","target":null,"required":null},{"title":"Два города","prompt":"Выведи имена пользователей из Москвы или Казани.","solution":"SELECT name FROM users WHERE city IN ('Москва','Казань')","hint1":"Можно использовать IN.","hint2":"Передай два города в скобках.","explanation":"IN проверяет принадлежность значению из списка.","mode":"read","target":null,"required":null},{"title":"Диапазон цен","prompt":"Покажи имена товаров с ценой от 500 до 4000 включительно.","solution":"SELECT name FROM products WHERE price BETWEEN 500 AND 4000","hint1":"Используй BETWEEN.","hint2":"BETWEEN включает обе границы.","explanation":"BETWEEN удобен для замкнутого диапазона.","mode":"read","target":null,"required":null},{"title":"Поиск в имени · финал","prompt":"Покажи имена пользователей, начинающиеся с буквы А.","solution":"SELECT name FROM users WHERE name LIKE 'А%'","hint1":"LIKE принимает шаблон.","hint2":"Процент означает любое продолжение строки.","explanation":"LIKE 'А%' находит строки с заданным началом.","mode":"read","target":null,"required":null}]},{"title":"Сортировка","topic":"ORDER BY · ASC · DESC · OFFSET","theory":"ORDER BY задаёт порядок строк. DESC сортирует по убыванию, ASC — по возрастанию. LIMIT и OFFSET помогают получать части результата.","example":"SELECT name, price\nFROM products\nORDER BY price DESC\nLIMIT 3;","required":null,"tasks":[{"title":"По цене","prompt":"Покажи названия и цены товаров от самых дорогих к дешёвым.","solution":"SELECT name, price FROM products ORDER BY price DESC","hint1":"Отсортируй по price.","hint2":"Для убывания добавь DESC.","explanation":"ORDER BY price DESC ставит высокие цены первыми.","mode":"read","target":null,"required":null},{"title":"Два самых молодых","prompt":"Выведи имена и возраст двух самых молодых пользователей.","solution":"SELECT name, age FROM users ORDER BY age ASC LIMIT 2","hint1":"Сортируй по age.","hint2":"Возьми первые две строки через LIMIT 2.","explanation":"По умолчанию сортировка идёт по возрастанию.","mode":"read","target":null,"required":null},{"title":"Возраст по убыванию","prompt":"Покажи name и age от старших к младшим.","solution":"SELECT name, age FROM users ORDER BY age DESC","hint1":"Используй ORDER BY age.","hint2":"Убывание обозначается DESC.","explanation":"ORDER BY меняет порядок строк результата.","mode":"read","target":null,"required":null},{"title":"Цена по возрастанию","prompt":"Покажи name и price от дешёвых к дорогим.","solution":"SELECT name, price FROM products ORDER BY price ASC","hint1":"Сортируй по price.","hint2":"ASC означает возрастание.","explanation":"ASC задаёт возрастающий порядок.","mode":"read","target":null,"required":null},{"title":"Дорогая пара","prompt":"Покажи name и price двух самых дорогих товаров.","solution":"SELECT name, price FROM products ORDER BY price DESC LIMIT 2","hint1":"Сначала отсортируй цены.","hint2":"Затем оставь две строки через LIMIT.","explanation":"LIMIT применяется к уже отсортированному результату.","mode":"read","target":null,"required":null},{"title":"Страница каталога","prompt":"Покажи name второго и третьего товаров по id.","solution":"SELECT name FROM products ORDER BY id LIMIT 2 OFFSET 1","hint1":"Сначала зафиксируй порядок по id.","hint2":"OFFSET 1 пропускает первую строку.","explanation":"LIMIT и OFFSET позволяют получать страницы результата.","mode":"read","target":null,"required":null},{"title":"Два ключа сортировки · финал","prompt":"Покажи city, name пользователей: сначала по городу, затем по имени.","solution":"SELECT city, name FROM users ORDER BY city, name","hint1":"ORDER BY принимает несколько столбцов.","hint2":"Перечисли city, затем name.","explanation":"Второй ключ сортирует строки с одинаковым первым ключом.","mode":"read","target":null,"required":null}]},{"title":"Агрегация","topic":"COUNT · SUM · AVG · GROUP BY","theory":"Агрегатные функции сводят множество строк к числу. GROUP BY создаёт группы, для каждой из которых можно вычислить COUNT, SUM или AVG.","example":"SELECT city, COUNT(*) AS total\nFROM users\nGROUP BY city;","required":"GROUP BY","tasks":[{"title":"Сколько пользователей","prompt":"Посчитай всех пользователей. Назови столбец total.","solution":"SELECT COUNT(*) AS total FROM users","hint1":"Используй COUNT(*).","hint2":"Добавь псевдоним AS total.","explanation":"COUNT(*) считает строки, включая строки с пустыми значениями.","mode":"read","target":null,"required":null},{"title":"По городам","prompt":"Посчитай пользователей в каждом городе. Выведи city и total.","solution":"SELECT city, COUNT(*) AS total FROM users GROUP BY city","hint1":"Нужно сгруппировать строки.","hint2":"Добавь GROUP BY city.","explanation":"GROUP BY city создаёт отдельную группу для каждого города.","mode":"read","target":null,"required":null},{"title":"Средняя цена","prompt":"Вычисли среднюю цену товаров как avg_price.","solution":"SELECT AVG(price) AS avg_price FROM products","hint1":"Используй AVG(price).","hint2":"Дай результату имя avg_price.","explanation":"AVG считает среднее по непустым значениям.","mode":"read","target":null,"required":null},{"title":"Сумма заказов","prompt":"Посчитай сумму всех заказов как revenue.","solution":"SELECT SUM(total) AS revenue FROM orders","hint1":"Нужна функция SUM.","hint2":"Передай ей столбец total.","explanation":"SUM складывает значения выбранного столбца.","mode":"read","target":null,"required":null},{"title":"Границы цен","prompt":"Покажи min_price и max_price для товаров.","solution":"SELECT MIN(price) AS min_price, MAX(price) AS max_price FROM products","hint1":"Нужны MIN и MAX.","hint2":"Назови два результирующих столбца.","explanation":"MIN и MAX находят границы набора значений.","mode":"read","target":null,"required":null},{"title":"Средняя цена категории","prompt":"Покажи category и avg_price для каждой категории.","solution":"SELECT category, AVG(price) AS avg_price FROM products GROUP BY category","hint1":"Группируй по category.","hint2":"Считай AVG(price) внутри каждой группы.","explanation":"GROUP BY делает отдельный расчёт для каждой категории.","mode":"read","target":null,"required":null},{"title":"Заказы покупателей · финал","prompt":"Покажи user_id и orders_count — число заказов каждого покупателя.","solution":"SELECT user_id, COUNT(*) AS orders_count FROM orders GROUP BY user_id","hint1":"Группируй по user_id.","hint2":"Для числа заказов используй COUNT(*).","explanation":"COUNT(*) считает заказы внутри каждой группы покупателя.","mode":"read","target":null,"required":null}]},{"title":"Фильтрация групп","topic":"HAVING","theory":"WHERE фильтрует исходные строки, а HAVING — уже посчитанные группы. Обычно HAVING стоит после GROUP BY.","example":"SELECT city, COUNT(*) AS total\nFROM users\nGROUP BY city\nHAVING COUNT(*) > 1;","required":"HAVING","tasks":[{"title":"Города с несколькими жителями","prompt":"Покажи city и total только для городов, где более одного пользователя.","solution":"SELECT city, COUNT(*) AS total FROM users GROUP BY city HAVING COUNT(*) > 1","hint1":"Сначала сгруппируй по городу.","hint2":"Отфильтруй группы через HAVING COUNT(*) > 1.","explanation":"HAVING проверяет размер уже сформированной группы.","mode":"read","target":null,"required":null},{"title":"Популярные категории","prompt":"Покажи category и total для категорий, где больше одного товара.","solution":"SELECT category, COUNT(*) AS total FROM products GROUP BY category HAVING COUNT(*) > 1","hint1":"Группируй по category.","hint2":"Для проверки количества групп используй HAVING.","explanation":"HAVING оставляет группы после подсчёта товаров.","mode":"read","target":null,"required":null},{"title":"Крупные заказы","prompt":"Покажи user_id и orders_count только для покупателей с двумя и более заказами.","solution":"SELECT user_id, COUNT(*) AS orders_count FROM orders GROUP BY user_id HAVING COUNT(*) >= 2","hint1":"Сначала группируй по user_id.","hint2":"Количество групп проверь через HAVING.","explanation":"HAVING отбирает покупателей после группировки заказов.","mode":"read","target":null,"required":null},{"title":"Дорогие категории","prompt":"Покажи category и avg_price для категорий со средней ценой выше 1000.","solution":"SELECT category, AVG(price) AS avg_price FROM products GROUP BY category HAVING AVG(price) > 1000","hint1":"Посчитай AVG(price) по category.","hint2":"Порог относится к группе, поэтому нужен HAVING.","explanation":"HAVING может сравнивать результат агрегатной функции.","mode":"read","target":null,"required":null},{"title":"Возраст городов","prompt":"Покажи city и avg_age для городов со средним возрастом выше 25.","solution":"SELECT city, AVG(age) AS avg_age FROM users GROUP BY city HAVING AVG(age) > 25","hint1":"Группируй по city.","hint2":"Условие по AVG(age) помести в HAVING.","explanation":"Группы фильтруются по своему среднему возрасту.","mode":"read","target":null,"required":null},{"title":"Сумма по покупателю","prompt":"Покажи user_id и revenue для покупателей с суммой заказов более 4000.","solution":"SELECT user_id, SUM(total) AS revenue FROM orders GROUP BY user_id HAVING SUM(total) > 4000","hint1":"Нужны SUM и GROUP BY.","hint2":"Отбирай группы через HAVING SUM(total) > 4000.","explanation":"Сумма заказов вычисляется отдельно по каждому user_id.","mode":"read","target":null,"required":null},{"title":"Категории с низкой ценой · финал","prompt":"Покажи category и min_price там, где минимальная цена ниже 500.","solution":"SELECT category, MIN(price) AS min_price FROM products GROUP BY category HAVING MIN(price) < 500","hint1":"Посчитай MIN(price) в группе.","hint2":"Проверь минимум через HAVING.","explanation":"HAVING работает с минимальным значением каждой категории.","mode":"read","target":null,"required":null}]},{"title":"Соединения","topic":"INNER JOIN · LEFT JOIN","theory":"JOIN объединяет строки двух таблиц по общему ключу. INNER JOIN оставляет совпадения, LEFT JOIN сохраняет и строки слева без пары.","example":"SELECT users.name, orders.total\nFROM users\nJOIN orders ON users.id = orders.user_id;","required":"JOIN","tasks":[{"title":"Покупатели и заказы","prompt":"Покажи имя пользователя и сумму каждого заказа: name, total.","solution":"SELECT users.name, orders.total FROM users JOIN orders ON users.id = orders.user_id","hint1":"Свяжи users и orders.","hint2":"Ключ связи: users.id = orders.user_id.","explanation":"JOIN сопоставил каждый заказ с его пользователем.","mode":"read","target":null,"required":null},{"title":"Все пользователи","prompt":"Покажи имя каждого пользователя и сумму заказа, если он есть: name, total. Сохрани пользователей без заказов.","solution":"SELECT users.name, orders.total FROM users LEFT JOIN orders ON users.id = orders.user_id","hint1":"Нужен LEFT JOIN.","hint2":"Таблица users должна стоять слева.","explanation":"LEFT JOIN сохраняет пользователей без заказов, показывая NULL в total.","mode":"read","target":null,"required":null},{"title":"ID заказа и имя","prompt":"Покажи orders.id как order_id и users.name для каждого заказа.","solution":"SELECT orders.id AS order_id, users.name FROM orders JOIN users ON orders.user_id = users.id","hint1":"Свяжи orders с users.","hint2":"Используй orders.user_id = users.id.","explanation":"JOIN добавляет к заказу данные его владельца.","mode":"read","target":null,"required":null},{"title":"Количество заказов для всех","prompt":"Покажи users.name и orders_count для всех пользователей, включая тех без заказов.","solution":"SELECT users.name, COUNT(orders.id) AS orders_count FROM users LEFT JOIN orders ON users.id = orders.user_id GROUP BY users.id","hint1":"Начни с users LEFT JOIN orders.","hint2":"Считай orders.id, чтобы отсутствующий заказ дал 0.","explanation":"LEFT JOIN сохраняет пользователей без заказа; COUNT(orders.id) даёт для них ноль.","mode":"read","target":null,"required":null},{"title":"Товары заказов","prompt":"Покажи orders.id как order_id и products.name как product_name для позиций заказов.","solution":"SELECT orders.id AS order_id, products.name AS product_name FROM orders JOIN order_items ON orders.id = order_items.order_id JOIN products ON order_items.product_id = products.id","hint1":"Нужны три таблицы.","hint2":"Свяжи orders → order_items → products.","explanation":"Два JOIN проходят через таблицу позиций заказа.","mode":"read","target":null,"required":null},{"title":"Сотрудник и отдел","prompt":"Покажи employees.name как employee и departments.name как department.","solution":"SELECT employees.name AS employee, departments.name AS department FROM employees JOIN departments ON employees.department_id = departments.id","hint1":"Соедини employees и departments.","hint2":"Ключ: department_id = departments.id.","explanation":"JOIN связывает внешний ключ сотрудника с отделом.","mode":"read","target":null,"required":null},{"title":"Сотрудник и руководитель · финал","prompt":"Покажи имя сотрудника как employee и имя его руководителя как manager, включая руководителей без начальника.","solution":"SELECT e.name AS employee, m.name AS manager FROM employees e LEFT JOIN employees m ON e.manager_id = m.id","hint1":"Это соединение таблицы с самой собой.","hint2":"Используй псевдонимы e и m и LEFT JOIN.","explanation":"Самосоединение показывает иерархию сотрудников.","mode":"read","target":null,"required":null}]},{"title":"Подзапросы","topic":"IN · EXISTS · вложенный SELECT","theory":"Подзапрос — запрос внутри другого запроса. Его результат можно использовать в IN, EXISTS или сравнении со значением.","example":"SELECT name\nFROM users\nWHERE id IN (SELECT user_id FROM orders);","required":"SELECT","tasks":[{"title":"Пользователи с заказами","prompt":"Через подзапрос выведи имена пользователей, у которых есть заказы.","solution":"SELECT name FROM users WHERE id IN (SELECT user_id FROM orders)","hint1":"Подзапрос должен вернуть user_id.","hint2":"Используй WHERE id IN (...).","explanation":"IN сверяет id пользователя со списком id из заказов.","mode":"read","target":null,"required":null},{"title":"Товары дороже среднего","prompt":"Выведи названия товаров с ценой выше средней по всем товарам.","solution":"SELECT name FROM products WHERE price > (SELECT AVG(price) FROM products)","hint1":"Найди среднюю цену через AVG.","hint2":"Помести SELECT AVG(price) в скобки.","explanation":"Скалярный подзапрос вычислил порог для сравнения.","mode":"read","target":null,"required":null},{"title":"Старше среднего","prompt":"Выведи имена пользователей старше среднего возраста.","solution":"SELECT name FROM users WHERE age > (SELECT AVG(age) FROM users)","hint1":"Сначала вычисли AVG(age).","hint2":"Помести вычисление в подзапрос в WHERE.","explanation":"Скалярный подзапрос возвращает порог для сравнения.","mode":"read","target":null,"required":null},{"title":"Покупатели без заказов","prompt":"Выведи имена пользователей, для которых нет заказов, через NOT EXISTS.","solution":"SELECT name FROM users u WHERE NOT EXISTS (SELECT 1 FROM orders o WHERE o.user_id = u.id)","hint1":"Нужен коррелированный подзапрос.","hint2":"Проверь o.user_id = u.id внутри NOT EXISTS.","explanation":"NOT EXISTS истинно, когда подзапрос не нашёл ни одной строки.","mode":"read","target":null,"required":null},{"title":"Товары в заказах","prompt":"Через IN выведи имена товаров, которые встречаются в order_items.","solution":"SELECT name FROM products WHERE id IN (SELECT product_id FROM order_items)","hint1":"Подзапрос должен вернуть product_id.","hint2":"Сравни products.id с результатом через IN.","explanation":"IN проверяет товар по набору идентификаторов из позиций заказов.","mode":"read","target":null,"required":null},{"title":"Заказы выше среднего","prompt":"Покажи id заказов с суммой выше средней суммы заказа.","solution":"SELECT id FROM orders WHERE total > (SELECT AVG(total) FROM orders)","hint1":"Используй AVG(total) в подзапросе.","hint2":"Сравни внешний total с этим значением.","explanation":"Подзапрос вычисляет среднюю сумму один раз для сравнения.","mode":"read","target":null,"required":null},{"title":"Есть дорогой заказ · финал","prompt":"Выведи имена пользователей, у которых есть заказ с total > 5000, через EXISTS.","solution":"SELECT name FROM users u WHERE EXISTS (SELECT 1 FROM orders o WHERE o.user_id = u.id AND o.total > 5000)","hint1":"Подзапрос зависит от внешнего пользователя.","hint2":"Свяжи o.user_id = u.id и проверь total.","explanation":"EXISTS проверяет наличие подходящего заказа для каждой строки users.","mode":"read","target":null,"required":null}]},{"title":"Условная логика","topic":"CASE WHEN","theory":"CASE WHEN создаёт значение в зависимости от условия. Заканчивается ключевым словом END; псевдоним задаётся через AS.","example":"SELECT name, CASE WHEN age >= 18 THEN 'adult' ELSE 'minor' END AS status\nFROM users;","required":"CASE","tasks":[{"title":"Возрастная группа","prompt":"Покажи name и status: 'adult' при age >= 18, иначе 'minor'.","solution":"SELECT name, CASE WHEN age >= 18 THEN 'adult' ELSE 'minor' END AS status FROM users","hint1":"Начни с CASE WHEN age >= 18.","hint2":"После ELSE добавь END AS status.","explanation":"CASE вычисляет значение отдельно для каждой строки.","mode":"read","target":null,"required":null},{"title":"Ценовой сегмент","prompt":"Покажи name и segment: 'premium' при price >= 1000, иначе 'basic'.","solution":"SELECT name, CASE WHEN price >= 1000 THEN 'premium' ELSE 'basic' END AS segment FROM products","hint1":"Проверяй price >= 1000.","hint2":"Заверши выражение END AS segment.","explanation":"CASE помогает классифицировать товары в запросе.","mode":"read","target":null,"required":null},{"title":"Метка города","prompt":"Покажи name и region: 'capital' для Москвы, иначе 'other'.","solution":"SELECT name, CASE WHEN city = 'Москва' THEN 'capital' ELSE 'other' END AS region FROM users","hint1":"Условие относится к city.","hint2":"Используй CASE WHEN ... THEN ... ELSE ... END.","explanation":"CASE создаёт текстовую метку по условию.","mode":"read","target":null,"required":null},{"title":"Бесплатная доставка","prompt":"Покажи id заказа и shipping: 'free' при total >= 5000, иначе 'paid'.","solution":"SELECT id, CASE WHEN total >= 5000 THEN 'free' ELSE 'paid' END AS shipping FROM orders","hint1":"Проверяй total >= 5000.","hint2":"Назови результат shipping.","explanation":"CASE формирует категорию для каждого заказа.","mode":"read","target":null,"required":null},{"title":"Три категории цены","prompt":"Покажи name и tier: 'low' при price < 1000, 'mid' при price < 5000, иначе 'high'.","solution":"SELECT name, CASE WHEN price < 1000 THEN 'low' WHEN price < 5000 THEN 'mid' ELSE 'high' END AS tier FROM products","hint1":"CASE может содержать несколько WHEN.","hint2":"Условия проверяются сверху вниз.","explanation":"Первое подходящее WHEN определяет значение tier.","mode":"read","target":null,"required":null},{"title":"Активный остаток","prompt":"Покажи id и availability: 'out' при quantity = 0, иначе 'in'.","solution":"SELECT id, CASE WHEN quantity = 0 THEN 'out' ELSE 'in' END AS availability FROM inventory","hint1":"Проверь quantity = 0.","hint2":"Заверши выражение END AS availability.","explanation":"CASE переводит числовой остаток в понятный статус.","mode":"read","target":null,"required":null},{"title":"Условный подсчёт · финал","prompt":"Посчитай взрослых пользователей как adults через SUM(CASE ...).","solution":"SELECT SUM(CASE WHEN age >= 18 THEN 1 ELSE 0 END) AS adults FROM users","hint1":"CASE вернёт 1 для взрослого.","hint2":"Сложи значения через SUM.","explanation":"SUM(CASE ...) считает строки, удовлетворяющие условию.","mode":"read","target":null,"required":null}]},{"title":"Даты и строки","topic":"date · UPPER · LENGTH","theory":"Функции SQL помогают преобразовывать даты и строки. В SQLite date() извлекает дату, UPPER() переводит текст в верхний регистр, LENGTH() считает символы.","example":"SELECT name, UPPER(city) AS city_upper\nFROM users;","required":null,"tasks":[{"title":"Город заглавными","prompt":"Покажи name и city_upper — город в верхнем регистре.","solution":"SELECT name, UPPER(city) AS city_upper FROM users","hint1":"Используй UPPER(city).","hint2":"Назови столбец city_upper.","explanation":"UPPER преобразует текст каждого значения city.","mode":"read","target":null,"required":null},{"title":"Дата заказа","prompt":"Покажи id и order_date — только дату без времени из created_at таблицы orders.","solution":"SELECT id, date(created_at) AS order_date FROM orders","hint1":"Используй date(created_at).","hint2":"Назови столбец order_date.","explanation":"date() извлекает календарную дату из времени заказа.","mode":"read","target":null,"required":null},{"title":"Нижний регистр","prompt":"Покажи name и city_lower — город в нижнем регистре.","solution":"SELECT name, LOWER(city) AS city_lower FROM users","hint1":"Используй LOWER(city).","hint2":"Псевдоним результата — city_lower.","explanation":"LOWER преобразует текст, не меняя исходные данные.","mode":"read","target":null,"required":null},{"title":"Длина имени","prompt":"Покажи name и name_length — количество символов в имени.","solution":"SELECT name, LENGTH(name) AS name_length FROM users","hint1":"Нужна функция LENGTH.","hint2":"Передай ей name и добавь псевдоним.","explanation":"LENGTH считает символы строки.","mode":"read","target":null,"required":null},{"title":"Почтовый домен","prompt":"Покажи email и domain — часть email после знака @.","solution":"SELECT email, SUBSTR(email, INSTR(email, '@') + 1) AS domain FROM users","hint1":"Найди позицию @ через INSTR.","hint2":"SUBSTR начни со следующего символа.","explanation":"INSTR находит позицию, SUBSTR извлекает хвост строки.","mode":"read","target":null,"required":null},{"title":"Месяц заказа","prompt":"Покажи id и month в формате YYYY-MM из created_at.","solution":"SELECT id, STRFTIME('%Y-%m', created_at) AS month FROM orders","hint1":"Используй STRFTIME.","hint2":"Формат для года и месяца: %Y-%m.","explanation":"STRFTIME форматирует дату по заданному шаблону.","mode":"read","target":null,"required":null},{"title":"Заказы после февраля · финал","prompt":"Выведи id заказов с датой created_at не раньше 1 марта 2026 года.","solution":"SELECT id FROM orders WHERE date(created_at) >= '2026-03-01'","hint1":"Сравни только календарную дату.","hint2":"Применяй date(created_at) в WHERE.","explanation":"date() отбрасывает время перед сравнением дат.","mode":"read","target":null,"required":null}]},{"title":"Продвинутый SQL","topic":"CTE · ROW_NUMBER · оконные функции","theory":"CTE через WITH делает сложный запрос читаемее. Оконные функции вычисляют значение для строки с учётом соседних строк, не сворачивая результат.","example":"SELECT name, price, ROW_NUMBER() OVER (ORDER BY price DESC) AS position\nFROM products;","required":"WITH","tasks":[{"title":"Рейтинг товаров","prompt":"Покажи name, price и position — номер товара в порядке убывания цены.","solution":"SELECT name, price, ROW_NUMBER() OVER (ORDER BY price DESC) AS position FROM products","hint1":"Используй ROW_NUMBER() OVER (...).","hint2":"В окне сортируй по price DESC.","explanation":"ROW_NUMBER нумерует строки в заданном порядке.","mode":"read","target":null,"required":null},{"title":"CTE дорогих товаров","prompt":"Через CTE expensive выведи имена товаров с price >= 1000.","solution":"WITH expensive AS (SELECT name FROM products WHERE price >= 1000) SELECT name FROM expensive","hint1":"Начни с WITH expensive AS (...).","hint2":"Затем SELECT name FROM expensive.","explanation":"CTE даёт имя промежуточному результату запроса.","mode":"read","target":null,"required":null},{"title":"CTE городов","prompt":"Через CTE city_counts покажи city и total пользователей по городам.","solution":"WITH city_counts AS (SELECT city, COUNT(*) AS total FROM users GROUP BY city) SELECT city, total FROM city_counts","hint1":"Сначала создай city_counts через WITH.","hint2":"Во внешнем запросе выбери city и total из CTE.","explanation":"CTE именует промежуточный результат группировки.","mode":"read","target":null,"required":null},{"title":"Ранг цены","prompt":"Покажи name и price_rank через RANK по убыванию price.","solution":"SELECT name, RANK() OVER (ORDER BY price DESC) AS price_rank FROM products","hint1":"Нужна оконная функция RANK().","hint2":"Сортировка находится внутри OVER.","explanation":"RANK присваивает одинаковый ранг равным значениям.","mode":"read","target":null,"required":null},{"title":"Сумма по категории","prompt":"Покажи name и category_total — сумму цен в категории товара.","solution":"SELECT name, SUM(price) OVER (PARTITION BY category) AS category_total FROM products","hint1":"Используй SUM(price) OVER (...).","hint2":"PARTITION BY category задаёт группы окна.","explanation":"Оконная SUM сохраняет каждую строку и добавляет итог её категории.","mode":"read","target":null,"required":null},{"title":"Накопительный итог","prompt":"Покажи id заказа и running_total — сумму заказов по возрастанию id.","solution":"SELECT id, SUM(total) OVER (ORDER BY id) AS running_total FROM orders","hint1":"Нужна оконная SUM.","hint2":"В OVER укажи ORDER BY id.","explanation":"Оконная сумма с порядком даёт накопительный итог.","mode":"read","target":null,"required":null},{"title":"Номер в отделе · финал","prompt":"Покажи name и position — номер сотрудника по убыванию зарплаты внутри отдела.","solution":"SELECT name, ROW_NUMBER() OVER (PARTITION BY department_id ORDER BY salary DESC) AS position FROM employees","hint1":"Нужны PARTITION BY и ORDER BY в окне.","hint2":"Раздели по department_id, отсортируй по salary DESC.","explanation":"ROW_NUMBER перезапускает нумерацию в каждом отделе.","mode":"read","target":null,"required":null}]},{"title":"NULL и уникальные значения","topic":"IS NULL · COALESCE · DISTINCT","theory":"NULL означает отсутствие значения. Сравнивать его через = нельзя: используй IS NULL или IS NOT NULL. COALESCE подставляет запасное значение, DISTINCT убирает повторы.","example":"SELECT id, COALESCE(rating, 0) AS rating\nFROM reviews;","required":null,"tasks":[{"title":"Уникальные города","prompt":"Выведи каждый city из users только один раз.","solution":"SELECT DISTINCT city FROM users","hint1":"Используй DISTINCT после SELECT.","hint2":"Выбери только city.","explanation":"DISTINCT убирает повторяющиеся города.","mode":"read","target":null,"required":null},{"title":"Отзывы без оценки","prompt":"Выведи id отзывов, в которых rating отсутствует.","solution":"SELECT id FROM reviews WHERE rating IS NULL","hint1":"NULL проверяется особым оператором.","hint2":"Используй IS NULL, а не = NULL.","explanation":"IS NULL выбирает строки с отсутствующей оценкой.","mode":"read","target":null,"required":null},{"title":"Отзывы с оценкой","prompt":"Покажи id и rating отзывов, где оценка указана.","solution":"SELECT id, rating FROM reviews WHERE rating IS NOT NULL","hint1":"Проверь наличие значения.","hint2":"Используй IS NOT NULL.","explanation":"IS NOT NULL исключает отзывы без оценки.","mode":"read","target":null,"required":null},{"title":"Запасная оценка","prompt":"Покажи id и score, подставив 0 вместо пустого rating.","solution":"SELECT id, COALESCE(rating, 0) AS score FROM reviews","hint1":"Используй COALESCE.","hint2":"Первый аргумент — rating, второй — 0.","explanation":"COALESCE возвращает первое непустое значение.","mode":"read","target":null,"required":null},{"title":"Подсчёт оценок","prompt":"Покажи total_reviews и rated_reviews: число всех отзывов и число отзывов с оценкой.","solution":"SELECT COUNT(*) AS total_reviews, COUNT(rating) AS rated_reviews FROM reviews","hint1":"Сравни COUNT(*) и COUNT(rating).","hint2":"COUNT(rating) игнорирует NULL.","explanation":"COUNT(*) учитывает строки, COUNT(rating) — непустые оценки.","mode":"read","target":null,"required":null},{"title":"Средняя оценка · финал","prompt":"Покажи avg_rating — среднее только по указанным оценкам.","solution":"SELECT AVG(rating) AS avg_rating FROM reviews","hint1":"Используй AVG(rating).","hint2":"AVG автоматически пропускает NULL.","explanation":"Отсутствующая оценка не превращается в ноль при расчёте среднего.","mode":"read","target":null,"required":null}]},{"title":"Объединение результатов","topic":"UNION · UNION ALL · INTERSECT · EXCEPT","theory":"Операторы множеств соединяют результаты запросов с одинаковым числом столбцов. UNION убирает повторы, UNION ALL сохраняет их, INTERSECT оставляет общие строки, EXCEPT — строки только слева.","example":"SELECT city FROM users\nUNION\nSELECT city FROM departments;","required":"UNION","tasks":[{"title":"Все города","prompt":"Покажи единый список городов пользователей и отделов без повторов.","solution":"SELECT city FROM users UNION SELECT city FROM departments","hint1":"Оба SELECT должны возвращать city.","hint2":"Для удаления повторов используй UNION.","explanation":"UNION объединяет две выборки как множество.","mode":"read","target":null,"required":null},{"title":"Все записи городов","prompt":"Объедини города пользователей и отделов, сохранив повторы.","solution":"SELECT city FROM users UNION ALL SELECT city FROM departments","hint1":"Нужны два SELECT city.","hint2":"Повторы сохраняет UNION ALL.","explanation":"UNION ALL складывает результаты без удаления повторов.","mode":"read","target":null,"required":null},{"title":"Города в обеих таблицах","prompt":"Покажи города, которые есть и у пользователей, и у отделов.","solution":"SELECT city FROM users INTERSECT SELECT city FROM departments","hint1":"Ищи пересечение двух выборок.","hint2":"Используй INTERSECT.","explanation":"INTERSECT оставляет значения, найденные с обеих сторон.","mode":"read","target":null,"required":null},{"title":"Города без пользователей","prompt":"Покажи города отделов, в которых нет пользователей.","solution":"SELECT city FROM departments EXCEPT SELECT city FROM users","hint1":"Вычитай города пользователей из городов отделов.","hint2":"Слева должны стоять departments.","explanation":"EXCEPT оставляет строки левого запроса, отсутствующие справа.","mode":"read","target":null,"required":null},{"title":"Города без отделов","prompt":"Покажи города пользователей, где нет отделов.","solution":"SELECT city FROM users EXCEPT SELECT city FROM departments","hint1":"Порядок сторон важен.","hint2":"Слева должны стоять users.","explanation":"EXCEPT несимметричен: смена сторон меняет ответ.","mode":"read","target":null,"required":null},{"title":"Общий справочник · финал","prompt":"Покажи уникальные значения из users.city и products.category в одном столбце label.","solution":"SELECT city AS label FROM users UNION SELECT category AS label FROM products","hint1":"Оба SELECT должны иметь один столбец.","hint2":"Назови результирующий столбец label.","explanation":"UNION позволяет собрать общий список значений из разных источников.","mode":"read","target":null,"required":null}]},{"title":"Изменение данных","topic":"INSERT · UPDATE · DELETE","theory":"INSERT добавляет строки, UPDATE меняет существующие, DELETE удаляет. В этом модуле каждая попытка выполняется в отдельной копии учебной базы. Ни аккаунт, ни другие упражнения не меняются.","example":"UPDATE inventory\nSET quantity = 5\nWHERE id = 3;","required":null,"tasks":[{"title":"Новая позиция","prompt":"Добавь в inventory строку id=5, product_id=5, quantity=8, status='active'.","solution":"INSERT INTO inventory(id,product_id,quantity,status) VALUES(5,5,8,'active')","hint1":"Используй INSERT INTO inventory.","hint2":"Перечисли столбцы и значения в одном порядке.","explanation":"INSERT добавляет новую строку в учебную копию inventory.","mode":"write","target":"inventory","required":"INSERT"},{"title":"Две позиции","prompt":"Добавь строки (5,5,8,'active') и (6,5,3,'active') в inventory одним запросом.","solution":"INSERT INTO inventory(id,product_id,quantity,status) VALUES(5,5,8,'active'),(6,5,3,'active')","hint1":"VALUES может содержать несколько наборов.","hint2":"Раздели две группы значений запятой.","explanation":"Один INSERT может добавить несколько строк.","mode":"write","target":"inventory","required":"INSERT"},{"title":"Пополнение","prompt":"Измени quantity на 10 у строки inventory с id=3.","solution":"UPDATE inventory SET quantity = 10 WHERE id = 3","hint1":"Используй UPDATE ... SET.","hint2":"Обязательно ограничь строку через WHERE id = 3.","explanation":"UPDATE меняет выбранную строку, а WHERE защищает остальные.","mode":"write","target":"inventory","required":"UPDATE"},{"title":"Скидка остатков","prompt":"Увеличь quantity на 5 у всех позиций, где quantity меньше 5.","solution":"UPDATE inventory SET quantity = quantity + 5 WHERE quantity < 5","hint1":"В SET можно использовать прежнее значение.","hint2":"Условие quantity < 5 помести в WHERE.","explanation":"UPDATE поддерживает вычисления на основе текущих значений.","mode":"write","target":"inventory","required":"UPDATE"},{"title":"Удаление пустого","prompt":"Удали из inventory строки с quantity = 0.","solution":"DELETE FROM inventory WHERE quantity = 0","hint1":"Нужен DELETE FROM.","hint2":"Укажи WHERE quantity = 0.","explanation":"DELETE удаляет только строки, прошедшие условие.","mode":"write","target":"inventory","required":"DELETE"},{"title":"Смена статуса · финал","prompt":"Установи status='empty' для всех позиций с quantity = 0.","solution":"UPDATE inventory SET status = 'empty' WHERE quantity = 0","hint1":"Используй UPDATE inventory.","hint2":"Ограничь изменение условием по quantity.","explanation":"UPDATE помогает синхронизировать статус с остатком.","mode":"write","target":"inventory","required":"UPDATE"}]},{"title":"Структура таблиц","topic":"CREATE TABLE · PRIMARY KEY · NOT NULL · DEFAULT","theory":"CREATE TABLE описывает столбцы и ограничения. PRIMARY KEY идентифицирует строку, NOT NULL требует значение, DEFAULT задаёт значение по умолчанию. Каждое задание создаёт таблицу заново в отдельной памяти.","example":"CREATE TABLE sandbox_table (id INTEGER PRIMARY KEY, name TEXT);","required":"CREATE","tasks":[{"title":"Первая таблица","prompt":"Создай sandbox_table со столбцами id INTEGER PRIMARY KEY и name TEXT.","solution":"CREATE TABLE sandbox_table(id INTEGER PRIMARY KEY, name TEXT)","hint1":"Начни с CREATE TABLE sandbox_table.","hint2":"Описание столбцов помести в круглые скобки.","explanation":"CREATE TABLE определяет структуру новой таблицы.","mode":"schema","target":"sandbox_table","required":"CREATE"},{"title":"Обязательное имя","prompt":"Создай sandbox_table: id INTEGER PRIMARY KEY, name TEXT NOT NULL.","solution":"CREATE TABLE sandbox_table(id INTEGER PRIMARY KEY, name TEXT NOT NULL)","hint1":"Добавь NOT NULL после TEXT.","hint2":"Ограничение относится только к name.","explanation":"NOT NULL запрещает отсутствие имени в новых строках.","mode":"schema","target":"sandbox_table","required":"CREATE"},{"title":"Остаток по умолчанию","prompt":"Создай sandbox_table: id INTEGER PRIMARY KEY, quantity INTEGER NOT NULL DEFAULT 0.","solution":"CREATE TABLE sandbox_table(id INTEGER PRIMARY KEY, quantity INTEGER NOT NULL DEFAULT 0)","hint1":"После типа quantity добавь NOT NULL.","hint2":"Для начального значения используй DEFAULT 0.","explanation":"DEFAULT заполняет столбец, если значение не передано.","mode":"schema","target":"sandbox_table","required":"CREATE"},{"title":"Составной ключ","prompt":"Создай sandbox_table со столбцами order_id INTEGER, product_id INTEGER и составным PRIMARY KEY(order_id, product_id).","solution":"CREATE TABLE sandbox_table(order_id INTEGER, product_id INTEGER, PRIMARY KEY(order_id, product_id))","hint1":"Ключ задаётся после обоих столбцов.","hint2":"Используй PRIMARY KEY(order_id, product_id).","explanation":"Составной ключ идентифицирует строку парой значений.","mode":"schema","target":"sandbox_table","required":"CREATE"},{"title":"Несколько типов","prompt":"Создай sandbox_table: id INTEGER PRIMARY KEY, price REAL, category TEXT.","solution":"CREATE TABLE sandbox_table(id INTEGER PRIMARY KEY, price REAL, category TEXT)","hint1":"Выбери тип REAL для price.","hint2":"Укажи три столбца через запятую.","explanation":"Схема задаёт тип каждого столбца.","mode":"schema","target":"sandbox_table","required":"CREATE"},{"title":"Статус по умолчанию · финал","prompt":"Создай sandbox_table: id INTEGER PRIMARY KEY, status TEXT NOT NULL DEFAULT 'new', created_at TEXT.","solution":"CREATE TABLE sandbox_table(id INTEGER PRIMARY KEY, status TEXT NOT NULL DEFAULT 'new', created_at TEXT)","hint1":"Столбец status обязателен.","hint2":"Для него задай DEFAULT 'new'.","explanation":"Сочетание NOT NULL и DEFAULT гарантирует непустой исходный статус.","mode":"schema","target":"sandbox_table","required":"CREATE"}]},{"title":"Аналитические задачи","topic":"Несколько таблиц · CTE · окна","theory":"В реальной работе запросы связывают таблицы, агрегируют данные и сравнивают результат между группами. Сначала определяй зерно результата: одна строка на заказ, пользователя или категорию.","example":"SELECT u.name, SUM(o.total) AS revenue\nFROM users u JOIN orders o ON u.id=o.user_id\nGROUP BY u.id;","required":null,"tasks":[{"title":"Выручка по покупателю","prompt":"Покажи name и revenue — сумму заказов каждого покупателя с заказами.","solution":"SELECT u.name, SUM(o.total) AS revenue FROM users u JOIN orders o ON u.id=o.user_id GROUP BY u.id","hint1":"Свяжи users с orders.","hint2":"Группируй по пользователю и суммируй total.","explanation":"Одна строка результата соответствует покупателю.","mode":"read","target":null,"required":null},{"title":"Все покупатели и выручка","prompt":"Покажи name и revenue для всех пользователей; без заказов revenue должен быть 0.","solution":"SELECT u.name, COALESCE(SUM(o.total),0) AS revenue FROM users u LEFT JOIN orders o ON u.id=o.user_id GROUP BY u.id","hint1":"Используй LEFT JOIN.","hint2":"Подставь 0 через COALESCE(SUM(...),0).","explanation":"LEFT JOIN сохраняет всех пользователей, COALESCE заменяет отсутствующую сумму.","mode":"read","target":null,"required":null},{"title":"Категория заказанного товара","prompt":"Покажи order_id и category для каждого товара в заказах.","solution":"SELECT oi.order_id, p.category FROM order_items oi JOIN products p ON oi.product_id=p.id","hint1":"Начни с order_items.","hint2":"Свяжи её с products по product_id.","explanation":"JOIN добавляет категорию товара к каждой позиции заказа.","mode":"read","target":null,"required":null},{"title":"Доля дорогих товаров","prompt":"Покажи category и expensive_count — число товаров дороже 1000 в каждой категории.","solution":"SELECT category, SUM(CASE WHEN price > 1000 THEN 1 ELSE 0 END) AS expensive_count FROM products GROUP BY category","hint1":"Группируй по category.","hint2":"Для условного подсчёта используй SUM(CASE ...).","explanation":"Условная агрегация считает только дорогие товары внутри каждой категории.","mode":"read","target":null,"required":null},{"title":"Последний заказ","prompt":"Покажи user_id и last_order — дату последнего заказа каждого покупателя.","solution":"SELECT user_id, MAX(date(created_at)) AS last_order FROM orders GROUP BY user_id","hint1":"Группируй по user_id.","hint2":"Последнюю дату найдёт MAX(date(created_at)).","explanation":"MAX выбирает самую позднюю дату внутри группы.","mode":"read","target":null,"required":null},{"title":"Топ по выручке · финал","prompt":"Покажи name и revenue покупателей с заказами по убыванию выручки.","solution":"SELECT u.name, SUM(o.total) AS revenue FROM users u JOIN orders o ON u.id=o.user_id GROUP BY u.id ORDER BY revenue DESC","hint1":"Сначала посчитай выручку по пользователю.","hint2":"Отсортируй итог по revenue DESC.","explanation":"Итоговый запрос объединяет JOIN, GROUP BY, SUM и ORDER BY.","mode":"read","target":null,"required":null}]}];
export const SCHEMA_SQL = "\nCREATE TABLE users(id INTEGER PRIMARY KEY, name TEXT, email TEXT, age INTEGER, city TEXT);\nINSERT INTO users VALUES (1,'Алексей','alex@example.com',25,'Москва'),(2,'Иван','ivan@example.com',17,'Казань'),(3,'Анна','anna@example.com',31,'Москва'),(4,'Мария','maria@example.com',28,'Санкт-Петербург'),(5,'Павел','pavel@example.com',22,'Казань');\nCREATE TABLE products(id INTEGER PRIMARY KEY, name TEXT, price INTEGER, category TEXT);\nINSERT INTO products VALUES (1,'Ноутбук',75000,'Электроника'),(2,'Наушники',3500,'Электроника'),(3,'Книга',850,'Книги'),(4,'Тетрадь',200,'Книги'),(5,'Лампа',1800,'Дом');\nCREATE TABLE orders(id INTEGER PRIMARY KEY, user_id INTEGER, total INTEGER, created_at TEXT);\nINSERT INTO orders VALUES (1,1,3500,'2026-01-12 10:30:00'),(2,3,75000,'2026-02-03 14:20:00'),(3,1,850,'2026-03-18 09:15:00'),(4,4,1800,'2026-04-09 18:00:00');\n\nCREATE TABLE departments(id INTEGER PRIMARY KEY, name TEXT, city TEXT);\nINSERT INTO departments VALUES (1,'Разработка','Москва'),(2,'Продажи','Казань'),(3,'Поддержка','Тула');\nCREATE TABLE employees(id INTEGER PRIMARY KEY, name TEXT, department_id INTEGER, manager_id INTEGER, salary INTEGER);\nINSERT INTO employees VALUES (1,'Ольга',1,NULL,120000),(2,'Денис',1,1,90000),(3,'Елена',2,NULL,95000),(4,'Руслан',2,3,65000),(5,'Светлана',3,NULL,70000);\nCREATE TABLE order_items(id INTEGER PRIMARY KEY, order_id INTEGER, product_id INTEGER, quantity INTEGER);\nINSERT INTO order_items VALUES (1,1,2,1),(2,2,1,1),(3,3,3,1),(4,4,5,1);\nCREATE TABLE reviews(id INTEGER PRIMARY KEY, user_id INTEGER, product_id INTEGER, rating INTEGER, comment TEXT);\nINSERT INTO reviews VALUES (1,1,2,5,'Удобно'),(2,3,1,4,NULL),(3,4,5,NULL,'Без оценки'),(4,2,3,3,NULL);\nCREATE TABLE inventory(id INTEGER PRIMARY KEY, product_id INTEGER, quantity INTEGER, status TEXT);\nINSERT INTO inventory VALUES (1,1,4,'active'),(2,2,12,'active'),(3,3,0,'empty'),(4,4,25,'active');\n";
